#!/usr/bin/env python3
import json
import os
import sys
import time
import select
import shutil
import termios
import tty
import unicodedata
from json import JSONDecodeError

VERSION = "1.4.1"

HELP = """  json-tui {OPTIONS} [file]

    A JSON terminal UI

  OPTIONS:

      file                              A JSON file. Omit to read from stdin.
      -h, --help                        Display this help menu.
      -v, --version                     Print version.
      -k, --key, --keybinding           Display key binding.
      -f, --fullscreen                  Display the JSON in fullscreen, in an
                                        alternate buffer
      "--" can be used to terminate flag options and force all following
      arguments to be treated as positional options

    If no file is given, json-tui reads JSON from the standard input
    Please report bugs to:https://github.com/ArthurSonzogni/json-tui/issues
"""

ESC = "\x1b"
RESET = ESC + "[39m" + ESC + "[49m"
BLUE = ESC + "[94m" + ESC + "[49m"
GREEN = ESC + "[92m" + ESC + "[49m"
CYAN = ESC + "[96m" + ESC + "[49m"
YELLOW = ESC + "[93m" + ESC + "[49m"
RED = ESC + "[91m" + ESC + "[49m"
GREY = ESC + "[90m" + ESC + "[49m"
HEADER_CYAN = ESC + "[36m" + ESC + "[49m"
BOLD = ESC + "[1m"
BOLD_OFF = ESC + "[22m"
INV = ESC + "[7m"
INV_OFF = ESC + "[27m"


def keybinding_output() -> bytes:
    sep = "├" + "─" * 11 + "┼" + "─" * 16 + "┤"
    lines = [
        "┌" + "─" * 11 + "┬" + "─" * 16 + "┐",
        "│" + HEADER_CYAN + "keys       " + RESET + "│" + HEADER_CYAN + "action          " + RESET + "│",
        sep,
        "│Navigate   │← ↑ ↓ →         │",
        "│           │h j k l         │",
        "│           │Mouse::WheelUp  │",
        "│           │Mouse::WheelDown│",
        sep,
        "│Toggle     │enter           │",
        "│           │Mouse::Left     │",
        sep,
        "│Deep       │                │",
        "│ - Expand  │+               │",
        "│ - Collapse│-               │",
        sep,
        "│Exit       │Escape          │",
        "│           │q               │",
        sep,
        "│Navigate   │                │",
        "│ - first   │page-up         │",
        "│ - last    │page-down       │",
        "│ - top     │gg              │",
        "│ - bottom  │G               │",
        "└" + "─" * 11 + "┴" + "─" * 16 + "┘",
    ]
    return ("\r\n".join(lines)).encode("utf-8") + b"\x00\n"


def display_width(s: str) -> int:
    w = 0
    for ch in s:
        o = ord(ch)
        if o == 0 or (o < 32 and ch not in "\t"):
            continue
        if ch == "\t":
            w += 4
        elif unicodedata.east_asian_width(ch) in ("W", "F"):
            w += 2
        else:
            w += 1
    return w


def clean_string(s: str) -> str:
    out = []
    for ch in s:
        o = ord(ch)
        if ch == "\t":
            out.append("    ")
        elif ch in "\r\n":
            out.append(" ")
        elif o < 32:
            # FTXUI does not visibly render these control characters.
            continue
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def number_string(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    # Python's float repr matches the observable formatting for the usual JSON
    # cases (1200.0, 1e-06, -0.0, ...).
    return repr(v)


def primitive_text_and_color(v):
    if v is None:
        return "null", RED
    if isinstance(v, bool):
        return ("true" if v else "false"), YELLOW
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return number_string(v), CYAN
    if isinstance(v, str):
        return clean_string(v), GREEN
    return str(v), None


def colorize(text, color=None, selected=False, bold=False):
    if selected:
        if color:
            return INV + color + text + INV_OFF + RESET
        return INV + text + INV_OFF
    if bold:
        return BOLD + text + BOLD_OFF
    if color:
        return color + text + RESET
    return text


class Line:
    __slots__ = ("raw", "visible", "focus_id", "focus_col")

    def __init__(self):
        self.raw = ""
        self.visible = 0
        self.focus_id = None
        self.focus_col = 0

    def add(self, raw: str, visible_text: str = None):
        self.raw += raw
        self.visible += display_width(raw if visible_text is None else visible_text)

    def add_plain(self, text: str):
        self.raw += text
        self.visible += display_width(text)

    def mark_focus(self, focus_id):
        self.focus_id = focus_id
        self.focus_col = self.visible


class TuiState:
    def __init__(self):
        self.expanded = {}
        self.explicit_arrays = set()
        self.table_mode = {}
        self.selected = ("value", ())


def path_parent(path):
    if not path:
        return None
    return path[:-1]


def get_at(data, path):
    cur = data
    for p in path:
        cur = cur[p]
    return cur


def is_container(v):
    return isinstance(v, (dict, list))


def is_tableable(v):
    return isinstance(v, list) and len(v) > 0 and all(isinstance(x, dict) for x in v)


def is_expanded(v, path, state: TuiState):
    if not is_container(v):
        return False
    if path in state.expanded:
        return state.expanded[path]
    if path == ():
        return True
    if isinstance(v, dict):
        parent = path_parent(path)
        if parent in state.explicit_arrays:
            return False
        return True
    return False


def sorted_object_items(obj):
    return [(k, obj[k]) for k in sorted(obj.keys())]


def key_repr(k):
    # Keys in nlohmann's ordered map are shown as JSON strings. Keep unicode
    # literal, escape the characters that would break a one-line key.
    return json.dumps(str(k), ensure_ascii=False)


def add_key_prefix(line: Line, indent: int, key: str):
    line.add_plain(" " * indent)
    k = key_repr(key)
    line.add(colorize(k, BLUE), k)
    line.add_plain(": ")


def render_primitive_line(lines, v, path, state, indent, is_last, prefix_key=None):
    line = Line()
    if prefix_key is not None:
        add_key_prefix(line, indent, prefix_key)
    else:
        line.add_plain(" " * indent)
    text, color = primitive_text_and_color(v)
    fid = ("value", path)
    selected = state.selected == fid
    line.mark_focus(fid)
    line.add(colorize(text, color, selected=selected), text)
    if not is_last:
        line.add_plain(",")
    lines.append(line)


def render_collapsed_line(lines, v, path, state, indent, is_last, prefix_key=None):
    line = Line()
    if prefix_key is not None:
        add_key_prefix(line, indent, prefix_key)
    else:
        line.add_plain(" " * indent)
    fid = ("value", path)
    selected = state.selected == fid
    line.mark_focus(fid)
    token = "{...}" if isinstance(v, dict) else "[...]"
    # The comma is part of the bold/focused collapsed element in the original.
    shown = token + ("," if not is_last else "")
    line.add(colorize(shown, selected=selected, bold=not selected), shown)
    if isinstance(v, list) and is_tableable(v):
        line.add_plain("   ")
        tfid = ("table", path)
        if state.selected == tfid:
            line.mark_focus(tfid)
        label = "(table view)"
        line.add(colorize(label, GREY, selected=state.selected == tfid), label)
    lines.append(line)


def render_object(lines, obj, path, state, indent, is_last, prefix_key=None):
    expanded = is_expanded(obj, path, state)
    if not expanded:
        render_collapsed_line(lines, obj, path, state, indent, is_last, prefix_key)
        return

    line = Line()
    if prefix_key is not None:
        add_key_prefix(line, indent, prefix_key)
    else:
        line.add_plain(" " * indent)
    fid = ("value", path)
    selected = state.selected == fid
    line.mark_focus(fid)
    line.add(colorize("{", selected=selected, bold=not selected), "{")
    lines.append(line)

    items = sorted_object_items(obj)
    for i, (k, v) in enumerate(items):
        child_path = path + (k,)
        render_value(lines, v, child_path, state, indent + 2, i == len(items) - 1, prefix_key=k)

    close = Line()
    close.add_plain(" " * indent + "}")
    if not is_last:
        close.add_plain(",")
    lines.append(close)


def array_columns(arr):
    cols = []
    seen = set()
    for obj in arr:
        for k in sorted(obj.keys()):
            if k not in seen:
                seen.add(k)
                cols.append(k)
    return cols


def table_cell(v):
    if isinstance(v, (dict, list)):
        txt = "{...}" if isinstance(v, dict) else "[...]"
        return txt, None
    return primitive_text_and_color(v)


def pad_raw(raw, text, width):
    return raw + " " * max(0, width - display_width(text))


def render_table(lines, arr, path, state, indent, is_last, prefix_key=None):
    # First line: the toggle back to the array view. This line is focusable.
    line = Line()
    if prefix_key is not None:
        add_key_prefix(line, indent, prefix_key)
    else:
        line.add_plain(" " * indent)
    fid = ("table", path)
    line.mark_focus(fid)
    label = "(array view)"
    line.add(colorize(label, GREY, selected=state.selected == fid), label)
    lines.append(line)

    cols = array_columns(arr)
    idx_w = max(1, len(str(max(0, len(arr) - 1))))
    widths = []
    for c in cols:
        w = display_width(str(c))
        for row in arr:
            if c in row:
                txt, _ = table_cell(row[c])
                w = max(w, display_width(txt))
        widths.append(w)

    def border(left, mid, right, fill):
        l = Line()
        l.add_plain(" " * (indent + idx_w) + left)
        for i, w in enumerate(widths):
            l.add_plain(fill * w)
            l.add_plain(right if i == len(widths) - 1 else mid)
        return l

    if not cols:
        return
    lines.append(border("┏", "┳", "┓", "━"))

    header = Line()
    blank = " " * idx_w
    header.add(colorize(blank, GREY), blank)
    header.add_plain("┃")
    for i, c in enumerate(cols):
        txt = str(c)
        header.add_plain(txt + " " * (widths[i] - display_width(txt)))
        header.add_plain("┃")
    lines.append(header)
    lines.append(border("┡", "╇", "┩", "━"))

    for r, row in enumerate(arr):
        l = Line()
        idx = str(r).rjust(idx_w)
        l.add(colorize(idx, GREY), idx)
        l.add_plain("│")
        for i, c in enumerate(cols):
            if c in row:
                txt, col = table_cell(row[c])
                raw = colorize(txt + " " * (widths[i] - display_width(txt)), col)
                l.add(raw, txt + " " * (widths[i] - display_width(txt)))
            else:
                l.add_plain(" " * widths[i])
            l.add_plain("│")
        lines.append(l)
    bottom = border("└", "┴", "┘", "─")
    if not is_last:
        # In practice table view is an array representation; retain no comma in
        # the common root case. For nested tables a comma after the border is a
        # reasonable approximation.
        pass
    lines.append(bottom)


def render_array(lines, arr, path, state, indent, is_last, prefix_key=None):
    if state.table_mode.get(path, False) and is_tableable(arr):
        render_table(lines, arr, path, state, indent, is_last, prefix_key)
        return
    expanded = is_expanded(arr, path, state)
    if not expanded:
        render_collapsed_line(lines, arr, path, state, indent, is_last, prefix_key)
        return

    line = Line()
    if prefix_key is not None:
        add_key_prefix(line, indent, prefix_key)
    else:
        line.add_plain(" " * indent)
    fid = ("value", path)
    selected = state.selected == fid
    line.mark_focus(fid)
    line.add(colorize("[", selected=selected, bold=not selected), "[")
    if is_tableable(arr):
        line.add_plain("   ")
        tfid = ("table", path)
        if state.selected == tfid:
            line.mark_focus(tfid)
        label = "(table view)"
        line.add(colorize(label, GREY, selected=state.selected == tfid), label)
    lines.append(line)

    for i, v in enumerate(arr):
        child_path = path + (i,)
        render_value(lines, v, child_path, state, indent + 2, i == len(arr) - 1)

    close = Line()
    close.add_plain(" " * indent + "]")
    if not is_last:
        close.add_plain(",")
    lines.append(close)


def render_value(lines, v, path, state, indent, is_last, prefix_key=None):
    if isinstance(v, dict):
        render_object(lines, v, path, state, indent, is_last, prefix_key)
    elif isinstance(v, list):
        render_array(lines, v, path, state, indent, is_last, prefix_key)
    else:
        render_primitive_line(lines, v, path, state, indent, is_last, prefix_key)


def build_lines(data, state):
    lines = []
    render_value(lines, data, (), state, 0, True)
    return lines


def collect_value_focus(data, state):
    order = []

    def rec(v, path):
        order.append(("value", path))
        if isinstance(v, dict) and is_expanded(v, path, state):
            for k, child in sorted_object_items(v):
                rec(child, path + (k,))
        elif isinstance(v, list) and (not state.table_mode.get(path, False)) and is_expanded(v, path, state):
            for i, child in enumerate(v):
                rec(child, path + (i,))

    rec(data, ())
    return order


def visible_value_paths(data, state):
    return set(collect_value_focus(data, state))


def nearest_visible_selection(data, state):
    value_order = collect_value_focus(data, state)
    all_values = set(value_order)
    if state.selected in all_values:
        return
    if state.selected[0] == "table":
        p = state.selected[1]
        # keep a visible table toggle selected when possible
        try:
            v = get_at(data, p)
            if isinstance(v, list) and is_tableable(v):
                parent_visible = ("value", p) in all_values or state.table_mode.get(p, False)
                if parent_visible:
                    return
        except Exception:
            pass
    # Walk up to an ancestor; otherwise root.
    if state.selected[0] in ("value", "table"):
        p = state.selected[1]
        while p:
            p = p[:-1]
            if ("value", p) in all_values:
                state.selected = ("value", p)
                return
    state.selected = ("value", ())


def set_expanded_for_path(state, data, path, expanded):
    try:
        v = get_at(data, path)
    except Exception:
        return
    if not is_container(v):
        return
    state.expanded[path] = bool(expanded)
    if expanded and isinstance(v, list) and path != ():
        state.explicit_arrays.add(path)
    if not expanded:
        state.table_mode[path] = False


def toggle_selected(data, state):
    typ, path = state.selected
    if typ == "table":
        try:
            v = get_at(data, path)
        except Exception:
            return
        if isinstance(v, list) and is_tableable(v):
            state.table_mode[path] = not state.table_mode.get(path, False)
        return
    try:
        v = get_at(data, path)
    except Exception:
        return
    if is_container(v):
        cur = is_expanded(v, path, state)
        set_expanded_for_path(state, data, path, not cur)


def collapse_all(data, state):
    def rec(v, path):
        if isinstance(v, dict):
            if path != ():
                state.expanded[path] = False
                state.table_mode[path] = False
            for k, child in v.items():
                rec(child, path + (k,))
        elif isinstance(v, list):
            if path != ():
                state.expanded[path] = False
                state.table_mode[path] = False
            for i, child in enumerate(v):
                rec(child, path + (i,))
    rec(data, ())


def expand_deep_value(data, state, v, path):
    if isinstance(v, dict):
        state.expanded[path] = True
        for k, child in v.items():
            expand_deep_value(data, state, child, path + (k,))
    elif isinstance(v, list):
        state.expanded[path] = True
        if path != ():
            state.explicit_arrays.add(path)
        for i, child in enumerate(v):
            cpath = path + (i,)
            if isinstance(child, dict) and path != ():
                # Arrays that were explicitly opened in the observed UI show
                # their object elements as collapsed summaries.
                state.expanded[cpath] = False
            else:
                expand_deep_value(data, state, child, cpath)


def expand_selected(data, state):
    typ, path = state.selected
    if typ == "table":
        path = typ = path  # no-op marker; expand array view instead below
        path = state.selected[1]
    try:
        v = get_at(data, path)
    except Exception:
        return
    expand_deep_value(data, state, v, path)


def parse_keys(s: str):
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == "\x1b":
            # Escape sequences for cursor and page keys, or bare Escape.
            if i + 2 < len(s) and s[i + 1] == "[":
                c = s[i + 2]
                if c in "ABCD":
                    yield {"A": "up", "B": "down", "C": "right", "D": "left"}[c]
                    i += 3
                    continue
                if i + 3 < len(s) and s[i + 3] == "~":
                    if c == "5":
                        yield "pageup"
                    elif c == "6":
                        yield "pagedown"
                    i += 4
                    continue
            yield "quit"
            i += 1
            continue
        if ch == "q":
            yield "quit"; i += 1; continue
        if ch in "\r\n":
            yield "enter"; i += 1; continue
        if ch == "j":
            yield "down"; i += 1; continue
        if ch == "k":
            yield "up"; i += 1; continue
        if ch == "h":
            yield "left"; i += 1; continue
        if ch == "l":
            yield "right"; i += 1; continue
        if ch == "g" and i + 1 < len(s) and s[i + 1] == "g":
            yield "top"; i += 2; continue
        if ch == "G":
            yield "bottom"; i += 1; continue
        if ch == "+":
            yield "expand"; i += 1; continue
        if ch == "-":
            yield "collapse"; i += 1; continue
        i += 1


def apply_event(data, state, ev):
    nearest_visible_selection(data, state)
    order = collect_value_focus(data, state)
    if ev in ("down", "up", "top", "bottom", "pageup", "pagedown"):
        if state.selected[0] == "table":
            assoc = ("value", state.selected[1])
            idx = order.index(assoc) if assoc in order else 0
        else:
            idx = order.index(state.selected) if state.selected in order else 0
        if ev == "down":
            idx = min(len(order) - 1, idx + 1)
        elif ev == "up":
            idx = max(0, idx - 1)
        elif ev in ("top", "pageup"):
            idx = 0
        elif ev in ("bottom", "pagedown"):
            idx = len(order) - 1
        state.selected = order[idx]
        return
    if ev == "right":
        if state.selected[0] == "value":
            path = state.selected[1]
            try:
                v = get_at(data, path)
            except Exception:
                return
            if isinstance(v, list) and is_tableable(v):
                state.selected = ("table", path)
        return
    if ev == "left":
        if state.selected[0] == "table":
            state.selected = ("value", state.selected[1])
        return
    if ev == "enter":
        toggle_selected(data, state)
        nearest_visible_selection(data, state)
        return
    if ev == "collapse":
        collapse_all(data, state)
        nearest_visible_selection(data, state)
        return
    if ev == "expand":
        expand_selected(data, state)
        nearest_visible_selection(data, state)
        return


def line_pad(line: Line, width: int) -> str:
    return line.raw + " " * max(0, width - line.visible)


def render_bytes(data, state, fullscreen=False):
    lines = build_lines(data, state)
    if not lines:
        lines = [Line()]
    # Ensure selected position is known and visible.
    selected_row = 0
    selected_col = 0
    for i, line in enumerate(lines):
        if line.focus_id == state.selected:
            selected_row = i
            selected_col = line.focus_col
            break
    term_cols, term_rows = shutil.get_terminal_size((80, 24))
    if fullscreen:
        width = term_cols
        total_lines = max(term_rows, len(lines))
    else:
        width = max(1, max(line.visible for line in lines))
        total_lines = len(lines)
    out = []
    out.append("\r" + ESC + "[2K" + line_pad(lines[0], width))
    for line in lines[1:]:
        out.append("\r\n" + line_pad(line, width))
    if fullscreen and total_lines > len(lines):
        blank = " " * width
        for _ in range(total_lines - len(lines)):
            out.append("\r\n" + blank)
    # Move the cursor back to the focused widget and hide it, as FTXUI does.
    up = total_lines - 1 - selected_row
    left = max(0, width - selected_col)
    if up:
        out.append(ESC + f"[{up}A")
    if left:
        out.append(ESC + f"[{left}D")
    out.append(ESC + "[?25l" + "\x00")
    return "".join(out).encode("utf-8"), (total_lines, width, selected_row, selected_col)


def start_bytes(fullscreen=False):
    s = "\x00" + ESC + "P$q q" + ESC + "\\"
    if fullscreen:
        s += ESC + "[?1049h"
    s += ESC + "[?7l" + ESC + "[?1000h" + ESC + "[?1003h" + ESC + "[?1015h" + ESC + "[?1006h" + "\x00"
    return s.encode("utf-8")


def end_bytes(cursor_info, fullscreen=False):
    total_lines, width, row, col = cursor_info
    down = total_lines - 1 - row
    right = max(0, width - col)
    s = ""
    if down:
        s += ESC + f"[{down}B"
    if right:
        s += ESC + f"[{right}C"
    s += ESC + "[?1006l" + ESC + "[?1015l" + ESC + "[?1003l" + ESC + "[?1000l" + ESC + "[?7h"
    if fullscreen:
        s += ESC + "[?1049l"
    s += ESC + "[?25h" + ESC + "[1 q" + "\x00" + "\r\n"
    return s.encode("utf-8")


def draw_once(data, state, fullscreen=False, finish=True):
    rb, info = render_bytes(data, state, fullscreen)
    sys.stdout.buffer.write(start_bytes(fullscreen) + rb)
    if finish:
        sys.stdout.buffer.write(end_bytes(info, fullscreen))
    sys.stdout.buffer.flush()
    return info


def clear_previous(info):
    total_lines, width, row, col = info
    # Move from focused position to bottom-right, then clear each rendered row.
    s = ""
    down = total_lines - 1 - row
    right = max(0, width - col)
    if down:
        s += ESC + f"[{down}B"
    if right:
        s += ESC + f"[{right}C"
    # Clear current line and walk upward.
    for i in range(total_lines):
        s += "\r" + ESC + "[2K"
        if i != total_lines - 1:
            s += ESC + "[1A"
    return s.encode("utf-8")


def interactive_tty(data, state, fullscreen=False):
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    info = None
    try:
        tty.setraw(fd)
        sys.stdout.buffer.write(start_bytes(fullscreen))
        rb, info = render_bytes(data, state, fullscreen)
        sys.stdout.buffer.write(rb)
        sys.stdout.buffer.flush()
        buf = ""
        while True:
            ch = os.read(fd, 1).decode("utf-8", "ignore")
            if not ch:
                continue
            if ch == "\x1b":
                # collect a likely escape sequence if immediately available
                time.sleep(0.01)
                while select.select([fd], [], [], 0)[0]:
                    ch += os.read(fd, 1).decode("utf-8", "ignore")
            events = list(parse_keys(ch))
            if any(e == "quit" for e in events):
                break
            for ev in events:
                apply_event(data, state, ev)
            sys.stdout.buffer.write(clear_previous(info))
            rb, info = render_bytes(data, state, fullscreen)
            sys.stdout.buffer.write(rb)
            sys.stdout.buffer.flush()
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        if info is None:
            info = (1, 1, 0, 0)
        sys.stdout.buffer.write(end_bytes(info, fullscreen))
        sys.stdout.buffer.flush()


def nlohmann_parse_error(doc: str, e: JSONDecodeError) -> str:
    # The original uses nlohmann/json. Recreate its common diagnostics closely.
    if doc == "" or doc.strip() == "":
        return "[json.exception.parse_error.101] parse error at line 1, column 1: attempting to parse an empty input; check that your input string or stream contains the expected JSON"
    pos = e.pos
    line = e.lineno
    col = e.colno
    ch = doc[pos] if pos < len(doc) else ""
    prefix = f"[json.exception.parse_error.101] parse error at line {line}, column {col}: "
    stripped = doc[:pos+1]
    if e.msg.startswith("Unterminated string"):
        start = doc.rfind('"', 0, pos + 1)
        last = doc[start:] if start >= 0 else doc[:pos+1]
        return prefix + "syntax error while parsing value - invalid string: missing closing quote; last read: '" + last + "'"
    if e.msg.startswith("Extra data"):
        tail = doc[pos:].lstrip()
        if tail.startswith("false"):
            return prefix + "syntax error while parsing value - unexpected false literal; expected end of input"
        if tail.startswith("true"):
            return prefix + "syntax error while parsing value - unexpected true literal; expected end of input"
        if tail.startswith("null"):
            return prefix + "syntax error while parsing value - unexpected null literal; expected end of input"
        return prefix + "syntax error while parsing value - unexpected token; expected end of input"
    if "property name" in e.msg:
        if pos >= len(doc):
            return prefix + "syntax error while parsing object key - unexpected end of input; expected string literal"
        return prefix + f"syntax error while parsing object key - unexpected '{ch}'; expected string literal"
    if e.msg.startswith("Expecting value"):
        if pos >= len(doc):
            return prefix + "syntax error while parsing value - unexpected end of input; expected '[', '{', or a literal"
        if ch in "}]":
            return prefix + f"syntax error while parsing value - unexpected '{ch}'; expected '[', '{{', or a literal"
        # invalid literal: nlohmann reports the consumed literal fragment.
        j = pos
        while j < len(doc) and (doc[j].isalpha() or doc[j] in "+-.0123456789"):
            j += 1
        last = doc[pos:j] or ch
        # For literals like "not json", nlohmann has consumed the first bad
        # two letters by the time it reports the error. Keep that behavior for
        # alphabetic fragments longer than one char.
        if len(last) > 2 and last.isalpha():
            last = last[:2] if last[0] == 'n' else last
        adj_col = col + (len(last) - 1 if len(last) > 1 else 0)
        return f"[json.exception.parse_error.101] parse error at line {line}, column {adj_col}: syntax error while parsing value - invalid literal; last read: '{last}'"
    if e.msg.startswith("Expecting ',' delimiter"):
        if ch and ch.isdigit():
            return prefix + "syntax error while parsing array - unexpected number literal; expected ']'"
    return prefix + e.msg


def parse_json(doc: str):
    try:
        return json.loads(doc, parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
    except JSONDecodeError as e:
        raise e
    except ValueError:
        # NaN/Infinity-like constants.
        raise JSONDecodeError("Expecting value", doc, 0)


def parse_args(argv):
    help_flag = version_flag = key_flag = fullscreen = False
    positional = []
    stop = False
    invalid = False
    for arg in argv:
        if not stop and arg == "--":
            stop = True
            continue
        if not stop and arg.startswith("--"):
            if arg == "--help":
                help_flag = True
            elif arg == "--version":
                version_flag = True
            elif arg in ("--key", "--keybinding"):
                key_flag = True
            elif arg == "--fullscreen":
                fullscreen = True
            else:
                invalid = True
        elif not stop and arg.startswith("-") and arg != "-" and len(arg) > 1:
            for c in arg[1:]:
                if c == "h":
                    help_flag = True
                elif c == "v":
                    version_flag = True
                elif c == "k":
                    key_flag = True
                elif c == "f":
                    fullscreen = True
                else:
                    invalid = True
                    break
        else:
            positional.append(arg)
    if len(positional) > 1:
        invalid = True
    return invalid, help_flag, version_flag, key_flag, fullscreen, positional


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    invalid, help_flag, version_flag, key_flag, fullscreen, positional = parse_args(argv)
    if invalid:
        sys.stderr.write("Invalid arguments\n")
        return 1
    if help_flag:
        sys.stdout.write(HELP)
        return 0
    if version_flag:
        sys.stdout.write(VERSION + "\n")
        return 0
    if key_flag:
        sys.stdout.buffer.write(keybinding_output())
        return 0

    if positional:
        filename = positional[0]
        try:
            with open(filename, "r", encoding="utf-8") as f:
                doc = f.read()
        except OSError:
            sys.stderr.write(f"Could not open file {filename}\n")
            return 1
        key_source_is_stdin = True
    else:
        sys.stdout.write("Reading from stdin...\n")
        sys.stdout.flush()
        doc = sys.stdin.read()
        key_source_is_stdin = False
    try:
        data = parse_json(doc)
    except JSONDecodeError as e:
        sys.stderr.write("\n" + nlohmann_parse_error(doc, e) + "\n")
        return 1

    state = TuiState()

    if key_source_is_stdin:
        if sys.stdin.isatty():
            interactive_tty(data, state, fullscreen)
            return 0
        # Non-tty file mode: consume any queued key presses. If no quit key is
        # supplied, keep the process alive like the interactive original.
        keys = ""
        try:
            if select.select([sys.stdin], [], [], 0)[0]:
                keys = sys.stdin.read()
        except Exception:
            keys = ""
        quit_seen = False
        for ev in parse_keys(keys):
            if ev == "quit":
                quit_seen = True
                break
            apply_event(data, state, ev)
        draw_once(data, state, fullscreen, finish=quit_seen)
        if not quit_seen:
            try:
                while True:
                    time.sleep(3600)
            except KeyboardInterrupt:
                return 130
        return 0
    else:
        # JSON came from stdin; there is no separate input stream for controls.
        draw_once(data, state, fullscreen, finish=False)
        try:
            while True:
                time.sleep(3600)
        except KeyboardInterrupt:
            return 130


if __name__ == "__main__":
    raise SystemExit(main())
